"""Writes public/sources.json (what the Sources page shows) and copies the first-page images. Titles are taken from the bank so they always match the questions."""
import json, re, shutil, os
from collections import Counter
bank=json.load(open('/home/claude/bank/question_bank.json'))
APP='/home/claude/app'
def titles_for(fileno,order_key):
    seen={}
    for q in bank:
        if q['source_file_no']==fileno and q['topic']: seen.setdefault(q['topic'],order_key(q))
    return [t for t,_ in sorted(seen.items(),key=lambda kv:kv[1])]
cr=titles_for(1,lambda q:int(q['source_question_number']))
lip=titles_for(4,lambda q:int(q['id'].split('-')[1]))
S=[
 dict(id='comprehensive-review',match='A Comprehensive Review 1001',name='Anesthesia: A Comprehensive Review (5th edition)',byline='Brian A. Hall and Robert C. Chantigian · Elsevier',kind='PDF book',pages=293,cover='sources/comprehensive-review.jpg',
      about='A question-and-answer review book. Each chapter of questions is followed by its answers, explanations and references. The answer keys and explanations on this site come from the book itself.',titleLabel='Chapters',titles=cr),
 dict(id='arba-minch',match='Arba Minch Mock Exams 2025',name='Arba Minch University: Anesthesia Licensure Mock Exams 2025',byline='Department of Anesthesia, College of Medicine and Health Sciences · prepared by Instructor Fraol Husen',kind='PDF',pages=218,cover='sources/arba-minch.jpg',
      about='Mock questions for 2025 graduating students (800 are listed in the PDF; numbers 291–299 are missing from the file itself). The PDF has no answer key and no explanations, so every answer and explanation shown here was generated by AI, is labelled as such, and has not been verified. The PDF has no chapter titles.',titleLabel=None,titles=[]),
 dict(id='ehple',match='EHPLE Practice Test 2025',name='EHPLE Practice Test Booklet 2025: Anesthesia',byline='Ethiopian Health Professionals Licensing Examination · Ministry of Health, Ethiopia',kind='PDF booklet',pages=48,cover='sources/ehple.jpg',
      about='200 practice questions with the answer key printed in the booklet. The booklet has no explanations, so the explanations shown here are AI-written and labelled. It has no chapter titles.',titleLabel=None,titles=[]),
 dict(id='lippincott',match="Lippincott's 1001",name="Lippincott's Anesthesia Review: 1001 Questions and Answers",byline='Paul Sikka, Edward Bittner, Thomas Halaszynski, Thoha Pham and Ashish Sinha · Wolters Kluwer',kind='PDF book',pages=562,cover='sources/lippincott.jpg',
      about='Questions grouped into chapters, each followed by answers and explanations. The answer keys and explanations on this site come from the book itself.',titleLabel='Chapters',titles=lip),
 dict(id='seniors',match="Seniors' Questions",name="Seniors' Questions",byline='Word document (seniors_.docx)',kind='Word document',pages=13,cover='sources/seniors.jpg',
      about='34 questions with answers and explanations, shown exactly as written in the document and not independently verified. The document has no chapter titles.',titleLabel=None,titles=[]),
]
for s in S:
    have={q['topic'] for q in bank if q['source']==s['match'] if q['topic']} if False else None
os.makedirs(f'{APP}/public/sources',exist_ok=True)
for f,dst in (('c1-001.jpg','comprehensive-review'),('c2-001.jpg','arba-minch'),('c3-01.jpg','ehple'),('c4-001.jpg','lippincott'),('c5-01.jpg','seniors')):
    shutil.copy(f'/home/claude/sen/covers/{f}',f'{APP}/public/sources/{dst}.jpg')
json.dump(S,open(f'{APP}/public/sources.json','w'),indent=1,ensure_ascii=False)
print('CR titles',len(cr),cr[:3]); print('LIPP titles',len(lip),lip[:3],'...',lip[-1])
# every title must be a real topic in the bank
names={1:'A Comprehensive Review 1001',2:'Arba Minch University Mock Exams 2025',3:'EHPLE Practice Test 2025',4:"Lippincott's 1001",5:"Seniors' Questions"}
for q in bank:
    if q['source_file_no']==5 or True: pass
print('topics per source:',{names[k]:len({q['topic'] for q in bank if q['source_file_no']==k and q['topic']}) for k in names})
